Here's an implementation of this approach:
```javascript
function findSequences(arr) {
  if (arr.length === 1) {
    return [arr];
  }

  const first = arr[0];
  const remaining = arr.slice(1);
  const subSequences = findSequences(remaining);

  const sequences = [];

  for (let i = 0; i < subSequences.length; i++) {
    const subSequence = subSequences[i];

    for (let j = 0; j <= subSequence.length; j++) {
      const sequence = subSequence.slice(0, j).concat(first).concat(subSequence.slice(j));

      // check if sequence is a reverse order of an existing sequence in the array
      const reverse = sequence.slice().reverse();
      const index = sequences.findIndex(s => arraysEqual(s, reverse));
      if (index === -1) {
        sequences.push(sequence);
      }
    }
  }

  return sequences;
}

function arraysEqual(a, b) {
  if (a.length !== b.length) {
    return false;
  }

  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) {
      return false;
    }
  }

  return true;
}
```
The `findSequences` function now fixes the first element in the array, generates all unique sequences without rotational shifts by only rearranging the remaining elements, and checks for reverse order duplicates before adding a new sequence to the result array.

Note that the `arraysEqual` function is used to compare arrays for equality, since the default `===` comparison operator does not work for arrays.

