I've created a simple word-guessing game for you, similar to Hangman. In this game, you'll have a limited number of attempts to guess a secret word by entering one letter at a time. After each guess, the game will show you the correctly guessed letters in their respective positions within the secret word, as well as the remaining attempts.

Here's the HTML and JavaScript code for the game. Save the code in a file with a `.html` extension, and then open it in your web browser to play the game.
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Simple Word Puzzle</title>
</head>
<body>
    <h1>Simple Word Puzzle</h1>
    <p>Guess the secret word one letter at a time!</p>
    <p id="masked-word">_ _ _ _ _</p>
    <p id="remaining-attempts"></p>
    <p id="message"></p>
    <input type="text" id="input-letter" placeholder="Enter a letter" maxlength="1" autocomplete="off">
    <button onclick="guess()">Submit Guess</button>

    <script>
        const secretWord = 'apple';
        const maxAttempts = 7;
        let remainingAttempts = maxAttempts;
        let guessedLetters = new Set();
        let maskedWord = '_'.repeat(secretWord.length);
        document.getElementById('remaining-attempts').innerHTML = `Remaining attempts: ${remainingAttempts}`;

        function guess() {
            const inputLetter = document.getElementById('input-letter').value.toLowerCase();
            if (inputLetter.length === 0 || inputLetter.charCodeAt(0) < 97 || inputLetter.charCodeAt(0) > 122) {
                document.getElementById('message').innerHTML = 'Please enter a valid letter (a-z).';
                return;
            }

            if (guessedLetters.has(inputLetter)) {
                document.getElementById('message').innerHTML = `You've already guessed "${inputLetter}". Try another letter.`;
                return;
            }

            guessedLetters.add(inputLetter);
            let correctGuess = false;
            let newMaskedWord = '';
            for (let i = 0; i < secretWord.length; i++) {
                if (inputLetter === secretWord[i]) {
                    newMaskedWord += inputLetter;
                    correctGuess = true;
                } else {
                    newMaskedWord += maskedWord[i];
                }
            }

            maskedWord = newMaskedWord;
            document.getElementById('masked-word').innerHTML = maskedWord.split('').join(' ');

            if (!correctGuess) {
                remainingAttempts--;
            }

            document.getElementById('remaining-attempts').innerHTML = `Remaining attempts: ${remainingAttempts}`;

            if (maskedWord === secretWord) {
                document.getElementById('message').innerHTML = 'Congratulations! You guessed the secret word!';
                document.getElementById('input-letter').disabled = true;
            } else if (remainingAttempts === 0) {
                document.getElementById('message').innerHTML = `Game over! The secret word was "${secretWord}".`;
                document.getElementById('input-letter').disabled = true;
            } else {
                document.getElementById('message').innerHTML = '';
            }

            document.getElementById('input-letter').value = '';
        }
    </script>
</body>
</html>
```
