expression: variable comparison_operator value;
variable: IDENTIFIER;
comparison_operator: '>' | '<' | '>=' | '<=' | '==' | '!=';
value: NUMBER | STRING | BOOLEAN;
logical_operator: 'AND' | 'OR' | 'NOT';

