To start, we'll create an HTML page with a `<canvas>` element where the game will be rendered. Inside the `<head>` tag, we'll include a `<style>` element with some basic CSS to set the canvas's dimensions and position it on the page.
```
<!DOCTYPE html>
<html>
  <head>
    <style>
      #game {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 500px;
        height: 500px;
        border: 1px solid black;
      }
    </style>
  </head>
  <body>
    <canvas id="game"></canvas>
  </body>
</html>
```
Next, we'll add some JavaScript to create the game logic. We'll start by getting a reference to the `<canvas>` element and setting up some variables to keep track of the player and enemies.
```
let canvas = document.getElementById("game");
let ctx = canvas.getContext("2d");

let player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  size: 20,
  speed: 3,
};

let enemies = [];
```
Now we can create a function to draw the player and enemies on the canvas. This function will be called on each frame of the game to update the positions and draw the squares.
```
function draw() {
  // Clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw the player
  ctx.fillStyle = "green";
  ctx.fillRect(player.x, player.y, player.size, player.size);

  // Draw the enemies
  ctx.fillStyle = "red";
  enemies.forEach(function(enemy) {
    ctx.fillRect(enemy.x, enemy.y, enemy.size, enemy.size);
  });
}
```
We also need a function to update the positions of the player and enemies on each frame. In this example, the enemies will move randomly and the player will be controlled by the arrow keys.
```
function update() {
  // Move the enemies
  enemies.forEach(function(enemy) {
    enemy.x += Math.random() * 2 - 1;
    enemy.y += Math.random() * 2 - 1;
  });

  // Move the player
  if (keys.ArrowUp) player.y -= player.speed;
  if (keys.ArrowDown) player.y += player.speed;
  if (keys.ArrowLeft) player.x -= player.speed;
  if (keys.ArrowRight) player.x += player.speed;
}
```
Finally, we can create a main game loop that calls the `update()` and `draw()` functions on each frame. We'll also add some event listeners to track when the player presses the arrow

keys and create a new enemy whenever the player clicks the mouse.
```
// Main game loop
function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

// Track pressed keys
let keys = {};
window.addEventListener("keydown", function(event) {
  keys[event.key] = true;
});
window.addEventListener("keyup", function(event) {
  keys[event.key] = false;
});

// Create a new enemy when the player clicks
