import os
import shutil
import subprocess
from pathlib import Path

from exceptions.exceptions import DataSourceException, ChecksumException
from operations.base import BaseOperation
class DownloadOperation(BaseOperation):
    def __init__(self, logger):
        super().__init__(logger)

    def process(self, data_source, source_path, encryption=False, zipping=False, checksum=False, s3_upload=False,
                archive=False, process_sub_folder=None, s3_path=None):
        try:
            self.logger.info("Downloading data from {} at {}...".format(data_source, source_path))
            if data_source == 'hdfs':
                self.download_from_hdfs(source_path)
            elif data_source == 'gpfs':
                self.download_from_gpfs(source_path)
            else:
                raise DataSourceException("Invalid data source type: {}".format(data_source))

            if encryption:
                self.encrypt_files(Path(os.getcwd()))

            if zipping:
                self.zip_directories(Path(os.getcwd()))

            if checksum:
                self.generate_checksums(Path(os.getcwd()))

            if s3_upload:
                self.upload_to_s3(Path(os.getcwd()), s3_path)

            if archive:
                self.archive_files(Path(os.getcwd()))

            if process_sub_folder:
                self.validate_checksum(process_sub_folder, s3_path)

            self.logger.info("Download completed successfully!")
