gamma_Cl = gamma_K;
gamma_Ba = 10^(-0.5*(2)^2*((sqrt(I)/(1+sqrt(I)))-(0.2*I)));
gamma_La = 10^(-0.5*(3)^2*((sqrt(I)/(1+sqrt(I)))-(0.2*I)));
gamma_plus = gamma_Ag;
gamma_minus = gamma_Cl;

% Calculate activity coefficient
log_gamma_plus = -0.5*(1)^2*((sqrt(I)/(1+sqrt(I)))-(0.2*I));
log_gamma_minus = log_gamma_plus;
gamma_plus = 10^log_gamma_plus;
gamma_minus = 10^log_gamma_minus;
gamma = sqrt(gamma_plus*gamma_minus);

% Print results
disp("Solubility of AgCl: " + S)
disp("Activity coefficient of AgCl: " + gamma)
